import type { Question } from '../../lib/types'
export const database_performance_questions: Question[] = [
  { id: 'd3-db-001', domain: 3, topics: ['DynamoDB', 'on-demand', 'provisioned'], type: 'single', stem: 'A DynamoDB table has unpredictable traffic with occasional bursts and long idle periods. Which capacity mode avoids throttling while minimizing costs?', options: [{ id: 'A', text: 'Provisioned with Auto Scaling — scales based on target utilization but lags during sudden bursts' }, { id: 'B', text: 'On-Demand capacity — automatically scales to accommodate any traffic instantly, charges per request' }, { id: 'C', text: 'Provisioned without Auto Scaling — fixed capacity, cheapest for perfectly predictable steady traffic' }, { id: 'D', text: 'DynamoDB Streams with consumer sharding to spread read load across multiple workers' }], correct: ['B'], explanation: 'On-Demand mode scales instantly to any traffic level with no provisioning. Charges per request. Best for truly unpredictable traffic. For predictable traffic, Provisioned + Auto Scaling is often cheaper.', distractors: { A: 'Provisioned + Auto Scaling reacts with lag — burst traffic can cause throttling during scale-out. On-Demand handles instantaneous bursts.', C: 'Fixed provisioned capacity throttles during bursts — expensive if over-provisioned for idle periods.', D: 'DynamoDB Streams is for change data capture — not a capacity mode for read/write throughput.' } },
  { id: 'd3-db-002', domain: 3, topics: ['DynamoDB', 'RCU', 'strongly consistent'], type: 'single', stem: 'A DynamoDB application switches from eventually consistent to strongly consistent reads. How does this affect RCU consumption?', options: [{ id: 'A', text: 'Strongly consistent reads consume 0.5 RCU per 4 KB — same as eventually consistent' }, { id: 'B', text: 'Strongly consistent reads consume 1 RCU per 4 KB — twice the cost of eventually consistent reads' }, { id: 'C', text: 'Strongly consistent reads cost 4x more because they read from all AZ replicas simultaneously' }, { id: 'D', text: 'Strongly consistent reads consume 2 RCUs per 4 KB for cross-region tables only' }], correct: ['B'], explanation: 'Eventually consistent reads: 0.5 RCU per 4 KB. Strongly consistent reads: 1 RCU per 4 KB — twice the cost. For read-heavy applications, using eventually consistent reads where acceptable reduces costs and increases throughput.', distractors: { A: '0.5 RCU is for eventually consistent reads — not strongly consistent, which costs double.', C: 'Strongly consistent reads cost 2x, not 4x — they do read from the leader node but the charge is 1 RCU per 4 KB.', D: 'Strongly consistent RCU cost is 1 per 4 KB for all tables, regardless of whether Global Tables is enabled.' } },
  { id: 'd3-db-003', domain: 3, topics: ['DynamoDB', 'GSI', 'query'], type: 'single', stem: 'A DynamoDB table has OrderId as the partition key and CustomerId as an attribute. Queries must filter by CustomerId efficiently. What enables this?', options: [{ id: 'A', text: 'Scan the table with a FilterExpression on CustomerId — returns matching items regardless of partition key' }, { id: 'B', text: 'Global Secondary Index with CustomerId as the partition key — enables efficient Query by CustomerId' }, { id: 'C', text: 'Local Secondary Index on CustomerId with OrderId as the partition key — adds sort key access within the same partition' }, { id: 'D', text: 'DynamoDB Streams with Lambda to pre-compute and cache CustomerId lookup results in ElastiCache' }], correct: ['B'], explanation: 'A GSI with CustomerId as the partition key allows querying all orders for a customer efficiently. GSIs can have a different partition key from the base table and can be added to existing tables.', distractors: { A: 'Scan with FilterExpression reads every item then filters — O(n) cost regardless of matches, expensive for large tables.', C: 'LSIs must share the same partition key (OrderId) as the base table — CustomerId cannot be an LSI partition key.', D: 'Streams + Lambda + ElastiCache is a complex workaround — a GSI directly provides the needed query access.' } },
  { id: 'd3-db-004', domain: 3, topics: ['ElastiCache', 'Redis', 'lazy loading'], type: 'single', stem: 'An application queries RDS frequently for the same product catalog data. Response times are high. What caching pattern with ElastiCache Redis reduces database load most effectively?', options: [{ id: 'A', text: 'Write-through — update cache and database on every write, guaranteeing cache is always current' }, { id: 'B', text: 'Lazy loading (cache-aside) — check cache first, query DB on miss, store result with TTL' }, { id: 'C', text: 'Write-behind — write to cache immediately, then async to DB with background flush thread' }, { id: 'D', text: 'Read-through — cache fetches from DB automatically on miss, transparent to the application' }], correct: ['B'], explanation: 'Lazy loading: check cache → hit returns immediately → miss queries DB, stores result in cache with TTL. First call is slow, subsequent calls are fast. TTL ensures data freshness. Most common pattern for read-heavy workloads.', distractors: { A: 'Write-through writes to cache and DB on every write — adds write latency and may cache data that is never read.', C: 'Write-behind risks data loss on failure and adds implementation complexity — lazy loading is simpler and effective.', D: 'Read-through has the cache fetch from DB on miss automatically — similar to lazy loading but the cache layer is responsible, not the app.' } },
  { id: 'd3-db-005', domain: 3, topics: ['DynamoDB', 'hot partition', 'write sharding'], type: 'single', stem: 'A DynamoDB table uses StatusCode as the partition key. One value ("PENDING") receives 90% of writes, causing throttling. What is the root cause?', options: [{ id: 'A', text: 'DynamoDB tables have a maximum of 10 partitions that cannot be exceeded' }, { id: 'B', text: 'Hot partition — one key concentrates too much traffic on a single partition, exceeding its throughput limit' }, { id: 'C', text: 'PENDING is a reserved word in DynamoDB that causes routing issues' }, { id: 'D', text: 'String partition keys have lower throughput limits than numeric partition keys in DynamoDB' }], correct: ['B'], explanation: 'DynamoDB partitions data by partition key. Each partition has a throughput limit. If most traffic goes to PENDING, that partition gets throttled while others are idle. Solutions: add a random suffix or use write sharding.', distractors: { A: 'DynamoDB automatically creates more partitions as needed — there is no artificial 10-partition limit.', C: 'PENDING is not a reserved word in DynamoDB — it is a valid partition key value.', D: 'DynamoDB has the same throughput limits for string and numeric partition keys — the issue is value concentration, not key type.' } },
  { id: 'd3-db-006', domain: 3, topics: ['ElastiCache', 'Redis', 'Memcached'], type: 'single', stem: 'An application needs a caching solution supporting complex data types (sorted sets, hashes) and persistence across restarts. Which ElastiCache engine is correct?', options: [{ id: 'A', text: 'Memcached — simpler architecture with multi-threaded performance but no persistence support' }, { id: 'B', text: 'Redis — supports sorted sets, hashes, lists, sets, persistence (RDB/AOF), replication, and pub/sub' }, { id: 'C', text: 'Both Memcached and Redis support sorted sets and persistence equally' }, { id: 'D', text: 'DynamoDB DAX — in-memory cache for complex data types including sorted sets and hashes' }], correct: ['B'], explanation: 'Redis supports complex data types (sorted sets for leaderboards, hashes, lists, bitmaps), persistence (RDB/AOF), replication, and pub/sub. Memcached is simpler (strings only) with no persistence.', distractors: { A: 'Memcached does not support sorted sets, hashes, or persistence — Redis is required for these features.', C: 'Memcached has no persistence and no complex data types — they are fundamentally different products.', D: 'DynamoDB DAX is a DynamoDB-specific read-through cache — not a general-purpose cache with Redis data structures.' } },
  { id: 'd3-db-007', domain: 3, topics: ['DynamoDB', 'DAX', 'microsecond'], type: 'single', stem: 'A DynamoDB table is read-heavy and millisecond latency is not meeting requirements. What purpose-built DynamoDB cache reduces read latency to microseconds?', options: [{ id: 'A', text: 'ElastiCache Redis in front of DynamoDB with custom cache-aside logic in the application' }, { id: 'B', text: 'Amazon DynamoDB Accelerator (DAX) — DynamoDB-compatible in-memory cache, microsecond latency, no code changes' }, { id: 'C', text: 'DynamoDB Streams with Lambda pre-computing results into a fast lookup table' }, { id: 'D', text: 'Provisioning higher RCUs on the table to reduce DynamoDB read response time' }], correct: ['B'], explanation: 'DAX is a fully managed DynamoDB-compatible in-memory cache. Provides microsecond latency for reads. API-compatible with DynamoDB — just point the SDK to the DAX cluster endpoint, no application code changes needed.', distractors: { A: 'ElastiCache Redis requires application code changes to implement cache-aside — DAX is transparent and DynamoDB API-compatible.', C: 'Streams + Lambda pre-computation adds latency for writes and complexity — DAX is a transparent read cache.', D: 'Higher provisioned RCUs improve service capacity — they reduce throttling but don\'t reduce DynamoDB\'s inherent single-digit millisecond latency.' } },
  { id: 'd3-db-008', domain: 3, topics: ['RDS', 'connection pooling', 'RDS Proxy'], type: 'single', stem: 'An RDS PostgreSQL database shows high connection overhead and wait times. A DBA suspects new connections are slow. What AWS service addresses connection overhead?', options: [{ id: 'A', text: 'Increase max_connections in the RDS parameter group to allow more parallel connections' }, { id: 'B', text: 'Amazon RDS Proxy — pools and reuses connections; applications get fast pool connections, DB sees fewer long-lived ones' }, { id: 'C', text: 'Upgrade to a larger DB instance type with more CPU for faster connection handling' }, { id: 'D', text: 'Enable RDS Multi-AZ to distribute connection load across primary and standby' }], correct: ['B'], explanation: 'RDS Proxy maintains a pool of long-lived connections to the DB. Applications connect to Proxy quickly (no TCP+SSL+auth overhead per request). Proxy manages a much smaller pool to the actual DB. Reduces connection establishment overhead significantly.', distractors: { A: 'max_connections allows more simultaneous connections — does not reduce the per-connection setup overhead.', C: 'Larger instances have more CPU/memory — does not reduce connection setup time for new TCP+SSL+auth cycles.', D: 'Multi-AZ standby does not serve live connections — it exists only for failover.' } },
  { id: 'd3-db-009', domain: 3, topics: ['DynamoDB', 'transactions', 'ACID'], type: 'single', stem: 'A banking app must atomically debit one DynamoDB account and credit another — either both succeed or neither does. What feature enables this?', options: [{ id: 'A', text: 'Conditional writes on both items separately — each write checks its own condition before committing' }, { id: 'B', text: 'TransactWriteItems — atomic all-or-nothing ACID transaction across up to 100 items' }, { id: 'C', text: 'DynamoDB Batch Write — submits multiple write requests in one API call for efficiency' }, { id: 'D', text: 'DynamoDB Global Tables — multi-region writes ensure consistency across both account records' }], correct: ['B'], explanation: 'TransactWriteItems supports atomic all-or-nothing operations across up to 100 items in same or different tables. All succeed or all fail with TransactionCanceledException. Provides ACID-like transactions in DynamoDB.', distractors: { A: 'Two separate conditional writes are not atomic together — a failure between them leaves inconsistent state.', C: 'Batch Write is best-effort — each operation is independent, not transactional.', D: 'Global Tables provides multi-region replication — not atomic multi-item transactions within a region.' } },
  { id: 'd3-db-010', domain: 3, topics: ['ElastiCache', 'Redis cluster', 'sharding'], type: 'single', stem: 'An ElastiCache Redis cluster is nearing memory limits. The dataset needs to scale horizontally. What Redis feature enables distributing data across multiple nodes?', options: [{ id: 'A', text: 'Redis Replication — create replicas of the primary to distribute the dataset across nodes' }, { id: 'B', text: 'Redis Cluster mode — shards data across multiple primary nodes, each responsible for a keyspace range' }, { id: 'C', text: 'Scale up to a larger node instance type to fit more data in a single node' }, { id: 'D', text: 'Add read replicas to the existing shard to increase available memory across the cluster' }], correct: ['B'], explanation: 'Redis Cluster mode (cluster mode enabled) partitions data across up to 500 shards. Each shard owns a subset of hash slots. Enables both horizontal memory scaling and high availability with replicas per shard.', distractors: { A: 'Replication creates copies of the same data for HA — each replica holds the full dataset, not a subset.', C: 'Vertical scaling is limited by the largest available instance size — cluster mode enables unlimited horizontal scaling.', D: 'Read replicas add read capacity within one shard — they hold a full copy of that shard\'s data, not additional memory capacity.' } },
  { id: 'd3-db-011', domain: 3, topics: ['DynamoDB', 'write sharding', 'hot partition'], type: 'single', stem: 'A DynamoDB table uses a timestamp as the partition key. All writes go to the most recent timestamp partition, causing throttling. What technique distributes writes?', options: [{ id: 'A', text: 'Use timestamps as the sort key instead — timestamps as sort keys distribute load across multiple partitions' }, { id: 'B', text: 'Write sharding — append a random suffix (e.g., 0-9) to the partition key to spread writes across partitions' }, { id: 'C', text: 'Switch to On-Demand capacity — removes throttling by automatically scaling to any traffic level instantly' }, { id: 'D', text: 'Use a composite key with the timestamp as both partition and sort key for better distribution' }], correct: ['B'], explanation: 'Write sharding appends a random number (e.g., 0-9) to the timestamp partition key. Writes distribute across 10 partitions instead of 1. Reads must query all N shards and aggregate — adds read complexity but solves the hot partition problem.', distractors: { A: 'Sort keys organize data within a partition — moving timestamps to the sort key still requires a useful partition key that distributes writes.', C: 'On-Demand handles burst traffic better but per-partition limits still apply — the hot partition problem exists regardless of capacity mode.', D: 'Using the same field as both partition and sort key is invalid — and doesn\'t solve the distribution problem.' } },
  { id: 'd3-db-012', domain: 3, topics: ['MemoryDB', 'Redis', 'durable primary database'], type: 'single', stem: 'An application uses Redis as its primary database (not just a cache) and requires microsecond latency with full data durability. What AWS service provides this?', options: [{ id: 'A', text: 'ElastiCache Redis with AOF persistence — asynchronous append-only file durability for Redis primary use' }, { id: 'B', text: 'Amazon MemoryDB for Redis — durable primary database with multi-AZ transaction log, microsecond latency' }, { id: 'C', text: 'DynamoDB with DAX in front — primary database with microsecond reads through the DAX cache layer' }, { id: 'D', text: 'ElastiCache Redis with Multi-AZ failover — replication provides durability when primary fails' }], correct: ['B'], explanation: 'MemoryDB is designed for Redis as a primary database: data stored in a distributed Multi-AZ transaction log for durability, microsecond read/write latency, survives cluster restarts without data loss.', distractors: { A: 'ElastiCache Redis AOF is slow and has recovery limitations — MemoryDB uses a proper transaction log for stronger durability guarantees.', C: 'DynamoDB + DAX is not Redis-compatible — applications using the Redis API would require code rewrites.', D: 'ElastiCache Redis Multi-AZ provides failover — data in the primary\'s write buffer can still be lost during failure.' } },
  { id: 'd3-db-013', domain: 3, topics: ['Aurora', 'Parallel Query', 'analytics'], type: 'single', stem: 'An Aurora MySQL database handles both OLTP and analytical queries. Long analytics queries degrade OLTP performance. What Aurora feature offloads analytics processing?', options: [{ id: 'A', text: 'Aurora read replicas — route all analytical queries to replicas to isolate from the primary OLTP node' }, { id: 'B', text: 'Aurora Parallel Query — pushes query processing to the storage layer, reducing OLTP interference on the compute layer' }, { id: 'C', text: 'Aurora Global Database — cross-region replica dedicated to analytics without impacting the primary region' }, { id: 'D', text: 'Aurora Multi-AZ — distributes OLTP and analytics workloads across primary and standby instances' }], correct: ['B'], explanation: 'Aurora Parallel Query offloads analytical query processing to the storage layer nodes. OLTP workloads see less contention because analytics queries don\'t compete for the buffer pool on the compute layer.', distractors: { A: 'Read replicas offload query processing but still compete for instance resources (CPU, memory, buffer pool) on the replica.', C: 'Global Database provides cross-region DR and low-latency reads — not a compute-layer analytics offload mechanism.', D: 'Multi-AZ standby does not serve live queries — it exists for failover only.' } },
  { id: 'd3-db-014', domain: 3, topics: ['DynamoDB', 'TTL', 'auto expiration'], type: 'single', stem: 'A DynamoDB table stores session data that should expire automatically after 24 hours. What feature handles automatic item deletion without consuming write capacity?', options: [{ id: 'A', text: 'DynamoDB Lifecycle rules — define retention period per table for automatic item expiration' }, { id: 'B', text: 'DynamoDB Time to Live (TTL) — set an epoch timestamp attribute; expired items are deleted automatically at no WCU cost' }, { id: 'C', text: 'DynamoDB Streams with Lambda — detect creation timestamp and delete expired items in a scheduled function' }, { id: 'D', text: 'Conditional writes with an expiry check — reject reads for items past their expiry epoch timestamp' }], correct: ['B'], explanation: 'DynamoDB TTL specifies an expiry epoch timestamp in a designated attribute. Items are deleted automatically within 48 hours after TTL time passes. Deletion is free — consumes no WCUs.', distractors: { A: 'DynamoDB has no "lifecycle rules" — TTL is the correct expiration feature.', C: 'Lambda scheduled deletion requires extra infrastructure and consumes WCUs for DeleteItem operations.', D: 'Conditional write checks reject stale writes — they don\'t delete expired items from the table.' } },
  { id: 'd3-db-015', domain: 3, topics: ['RDS', 'read replicas', 'read scaling'], type: 'single', stem: 'An RDS MySQL database handles 80% reads and 20% writes. What is the most effective optimization for this read-heavy workload?', options: [{ id: 'A', text: 'Upgrade to a larger RDS instance type for more CPU and memory to handle the read load' }, { id: 'B', text: 'Add RDS Read Replicas and route read traffic to them — offloads 80% of queries from the primary instance' }, { id: 'C', text: 'Enable Multi-AZ — the standby can serve read traffic during normal operation' }, { id: 'D', text: 'Increase max_connections parameter — allows more read queries to run concurrently on the primary' }], correct: ['B'], explanation: 'For read-heavy workloads, Read Replicas distribute the read load. Route SELECT queries to replicas and DML (INSERT/UPDATE/DELETE) to the primary. Up to 5 read replicas for MySQL.', distractors: { A: 'Vertical scaling helps but has limits and higher cost — horizontal read scaling via replicas is more scalable.', C: 'RDS Multi-AZ standby does not serve read traffic — it exists only for automatic failover.', D: 'max_connections allows more concurrent connections — it does not distribute the query load off the primary.' } },
  { id: 'd3-db-016', domain: 3, topics: ['DynamoDB', 'Scan vs Query', 'GSI'], type: 'single', stem: 'A developer uses Scan with FilterExpression to find DynamoDB items by email. With millions of items, performance is slow and costs are high. What is the correct fix?', options: [{ id: 'A', text: 'Increase provisioned throughput — more RCUs make the scan complete faster' }, { id: 'B', text: 'Create a GSI with email as the partition key — enables Query operations that read only matching items' }, { id: 'C', text: 'Use DynamoDB Streams to pre-index items by email into a separate lookup structure' }, { id: 'D', text: 'Partition the table by email range to reduce the scan scope to a single partition' }], correct: ['B'], explanation: 'Scan with FilterExpression reads every item then filters — O(n) cost. A GSI with email as the partition key allows Query operations reading only matching items — O(1) for a single email lookup.', distractors: { A: 'More RCUs make the scan faster but it still reads all items — the O(n) cost remains, just completes sooner.', C: 'Streams + separate lookup structure is complex to build and maintain — a GSI is the native DynamoDB solution.', D: 'DynamoDB partitioning is internal and not user-configurable by range — GSI is the correct access pattern solution.' } },
  { id: 'd3-db-017', domain: 3, topics: ['ElastiCache', 'Redis sorted sets', 'leaderboard'], type: 'single', stem: 'A gaming app needs a real-time leaderboard supporting score increments and top-100 retrieval. Which ElastiCache Redis data type is ideal?', options: [{ id: 'A', text: 'String with INCR — increment player scores individually and sort all strings to find the top 100' }, { id: 'B', text: 'Sorted Set (ZADD/ZREVRANGE) — stores members with scores, auto-sorted, O(log N) add and O(log N + M) range query' }, { id: 'C', text: 'Hash with player score fields — store all player scores in one hash and sort in the application layer' }, { id: 'D', text: 'List with score prefix — push score+player strings to a list and sort on read to find the top 100' }], correct: ['B'], explanation: 'Redis Sorted Sets: ZADD adds/updates a player\'s score, ZREVRANGE with LIMIT retrieves top N players sorted by score. O(log N) time complexity for all operations. Data stays sorted automatically.', distractors: { A: 'Strings with INCR can track individual scores but provide no sorted ordering — getting top 100 requires reading all scores and sorting in application.', C: 'Hashes store structured data but do not support sorted range queries — application-level sorting is O(n).', D: 'Lists support push/pop but do not maintain score ordering — sorting a list of strings is O(n log n) and not atomic.' } },
  { id: 'd3-db-018', domain: 3, topics: ['Aurora', 'custom endpoints', 'workload isolation'], type: 'single', stem: 'An Aurora cluster has 1 primary and 5 replicas. A reporting application runs complex queries that should not affect OLTP performance. How should connections be routed?', options: [{ id: 'A', text: 'Connect all queries to the writer endpoint — the primary handles both OLTP and reporting workloads' }, { id: 'B', text: 'Create a custom endpoint pointing to specific replicas for reporting — isolates reporting from OLTP read traffic' }, { id: 'C', text: 'Use the reader endpoint for all reads — it distributes across all 5 replicas including OLTP ones' }, { id: 'D', text: 'Connect directly to individual replica instance endpoints and manage routing in the application' }], correct: ['B'], explanation: 'Aurora custom endpoints route specific workloads to specific replica sets. Create a custom endpoint containing only dedicated replicas for reporting. Other replicas handle OLTP reads via the reader endpoint.', distractors: { A: 'Writing and running heavy analytics on the primary adds to primary load — replicas exist specifically to offload this.', C: 'The reader endpoint distributes across all replicas — reporting queries could land on replicas serving OLTP traffic.', D: 'Individual instance endpoints require manual management as replicas are added or replaced.' } },
  { id: 'd3-db-019', domain: 3, topics: ['DynamoDB', 'WCU calculation'], type: 'single', stem: 'A DynamoDB table writes 1,000 items per second, each 3 KB in size. How many WCUs are required?', options: [{ id: 'A', text: '1,000 WCUs — one WCU per write regardless of item size' }, { id: 'B', text: '3,000 WCUs — each 3 KB item costs 3 WCUs (1 WCU per 1 KB); 1,000 items/sec × 3 WCUs = 3,000' }, { id: 'C', text: '500 WCUs — WCU calculation uses 2 KB per unit for eventual consistency writes' }, { id: 'D', text: '750 WCUs — 3 KB rounds down to 2 KB, costing 2 WCUs per item; 1,000 × 0.75 WCUs average' }], correct: ['B'], explanation: 'WCU calculation: 1 WCU = 1 write per second up to 1 KB. A 3 KB item requires 3 WCUs (round up to nearest KB). For 1,000 items/sec × 3 WCUs = 3,000 WCUs.', distractors: { A: '1 WCU per write is only correct for items ≤1 KB — items over 1 KB require additional WCUs.', C: 'WCU uses 1 KB per unit (not 2 KB) — eventually consistent pricing is only for reads (RCUs), not writes.', D: 'WCU calculation rounds UP to the nearest KB — a 3 KB item costs 3 WCUs, not 2.' } },
  { id: 'd3-db-020', domain: 3, topics: ['RDS Proxy', 'Lambda', 'connection pooling'], type: 'single', stem: 'Lambda functions connecting to RDS cause connection exhaustion. Each invocation opens a new connection. What addresses this?', options: [{ id: 'A', text: 'Lambda can only connect to RDS via a proxy — direct connections are not supported by the VPC configuration' }, { id: 'B', text: 'RDS Proxy pools connections — Lambda invocations connect to Proxy (fast), Proxy maintains a small DB connection pool' }, { id: 'C', text: 'RDS Proxy caches Lambda query results to reduce the number of DB connections needed' }, { id: 'D', text: 'RDS Proxy enables Lambda to use DynamoDB-style connection sharing across concurrent invocations' }], correct: ['B'], explanation: 'Lambda can have thousands of concurrent instances each opening a DB connection. RDS Proxy maintains a pool and reuses connections — Lambda instances connect to Proxy quickly, Proxy manages the smaller DB connection pool.', distractors: { A: 'Lambda can connect directly to RDS — RDS Proxy is a recommendation to solve connection exhaustion, not a requirement.', C: 'RDS Proxy pools connections — it is not a query result cache.', D: 'RDS Proxy is for RDS/Aurora — DynamoDB has its own connection model and SDK, not relevant here.' } },
  { id: 'd3-db-021', domain: 3, topics: ['DynamoDB', 'GSI projections', 'storage cost'], type: 'single', stem: 'A DynamoDB table has 50 attributes. A GSI projects ALL attributes, increasing storage costs significantly. What reduces GSI storage cost?', options: [{ id: 'A', text: 'GSIs always project all attributes — the projection type cannot be changed after creation' }, { id: 'B', text: 'Configure GSI projection to INCLUDE only the attributes needed by queries — eliminates redundant attribute storage' }, { id: 'C', text: 'Use fewer GSIs on the table — each GSI removed reduces the total storage cost proportionally' }, { id: 'D', text: 'Switch from GSIs to LSIs — LSIs share the base table storage and avoid redundant attribute copies' }], correct: ['B'], explanation: 'GSI projections: KEYS_ONLY (cheapest), INCLUDE (specific attributes), ALL (most expensive). For a 50-attribute table, projecting only the 5 attributes needed by queries is dramatically cheaper than ALL.', distractors: { A: 'GSI projection type is set at creation and cannot be changed — but this is an argument for choosing INCLUDE correctly upfront.', C: 'Fewer GSIs reduce query flexibility — INCLUDE projection targets the specific cost optimization.', D: 'LSIs share base table storage — but they also cannot have a different partition key, limiting their use cases.' } },
  { id: 'd3-db-022', domain: 3, topics: ['Aurora Serverless v2', 'scaling speed'], type: 'single', stem: 'Aurora Serverless v2 is configured with min 0.5 ACUs and max 128 ACUs. How quickly does it scale up during a traffic spike?', options: [{ id: 'A', text: '5-10 minutes — same provisioning time as standard Aurora cluster instance changes' }, { id: 'B', text: 'Within seconds — Aurora Serverless v2 scales in 0.5 ACU increments, responding to load changes in near real-time' }, { id: 'C', text: '30-60 seconds — scaling requires a brief maintenance window for ACU reallocation' }, { id: 'D', text: 'Instantaneous but only within the same AZ — cross-AZ scaling requires 30 seconds' }], correct: ['B'], explanation: 'Aurora Serverless v2 scales in fine-grained increments (0.5 ACUs) and responds to load changes within seconds. Fundamentally different from v1 cold starts. Rapid scaling avoids latency spikes during traffic changes.', distractors: { A: '5-10 minutes is for provisioning new Aurora instances — Serverless v2 scales the existing cluster\'s compute in seconds.', C: 'Aurora Serverless v2 scaling does not require a maintenance window — it scales transparently.', D: 'ACU scaling is not AZ-bound — the scaling behavior is the same regardless of AZ placement.' } },
  { id: 'd3-db-023', domain: 3, topics: ['DynamoDB', 'item size limit'], type: 'single', stem: 'A developer tries to store a 600 KB item in DynamoDB. What happens, and what is the correct approach?', options: [{ id: 'A', text: 'DynamoDB accepts items up to 256 KB — 600 KB is rejected, reduce item size to fit within 256 KB' }, { id: 'B', text: 'DynamoDB rejects items over 400 KB — store the large payload in S3 and keep only the S3 key in DynamoDB' }, { id: 'C', text: 'DynamoDB accepts items up to 1 MB — 600 KB fits but costs double the standard WCU rate' }, { id: 'D', text: 'DynamoDB has no item size limit — items are only constrained by partition throughput limits' }], correct: ['B'], explanation: 'DynamoDB maximum item size is 400 KB (including all attribute names and values). Store large payloads in S3 and keep the S3 reference in DynamoDB — the standard pattern for large objects.', distractors: { A: '256 KB is not the DynamoDB item limit — 400 KB is the correct maximum.', C: '1 MB exceeds DynamoDB\'s 400 KB item size limit — the item would be rejected, not accepted at double cost.', D: 'DynamoDB enforces a 400 KB per-item limit — it is not unlimited.' } },
  { id: 'd3-db-024', domain: 3, topics: ['ElastiCache', 'online resharding', 'zero downtime'], type: 'single', stem: 'An ElastiCache Redis cluster mode enabled cluster is running out of memory. Zero downtime is required. How can memory be scaled?', options: [{ id: 'A', text: 'Restore the cluster from a backup with more shards configured in the new cluster' }, { id: 'B', text: 'Online resharding — add shards to the cluster while it remains operational, data redistributes automatically' }, { id: 'C', text: 'Scale up node instance types — larger nodes provide more memory per shard without adding shards' }, { id: 'D', text: 'Add read replicas to existing shards — each replica holds the full shard data, effectively doubling available memory' }], correct: ['B'], explanation: 'ElastiCache Redis cluster mode supports online resharding (adding or removing shards) without downtime. Data redistributes across the new shards automatically while the cluster continues to serve traffic.', distractors: { A: 'Backup restoration requires creating a new cluster and updating connection strings — causes downtime.', C: 'Scaling up node types increases memory per shard but is still bounded by the largest available instance size.', D: 'Read replicas hold the same data as the primary shard — they add read capacity, not total memory capacity.' } },
  { id: 'd3-db-025', domain: 3, topics: ['DynamoDB Streams', 'event-driven', 'Lambda'], type: 'single', stem: 'A company wants to trigger processing every time a DynamoDB item is created or updated. What is the native pattern for this?', options: [{ id: 'A', text: 'EventBridge Scheduler polling DynamoDB every minute and comparing timestamps' }, { id: 'B', text: 'DynamoDB Streams + Lambda — Streams captures item changes; Lambda processes change records as an event source' }, { id: 'C', text: 'SQS queue polling DynamoDB with a Scan for changed items since the last poll' }, { id: 'D', text: 'S3 Event Notifications triggered when DynamoDB exports to S3 for batch processing' }], correct: ['B'], explanation: 'DynamoDB Streams captures a time-ordered sequence of item changes (INSERT, MODIFY, REMOVE). Lambda can be configured as an event source for the stream — invoked with batches of change records within milliseconds.', distractors: { A: 'EventBridge Scheduler with DynamoDB polling adds latency and requires change tracking logic — Streams is the native push-based approach.', C: 'SQS does not integrate with DynamoDB natively for change detection — this approach requires complex polling logic.', D: 'DynamoDB Export to S3 is for bulk analytics snapshots — not real-time item change processing.' } },
  { id: 'd3-db-026', domain: 3, topics: ['RDS', 'memory-optimized', 'cache miss'], type: 'single', stem: 'An RDS PostgreSQL database with a 200 GB dataset has a high cache miss ratio and frequently reads from disk. What is the most effective performance fix?', options: [{ id: 'A', text: 'Add RDS Read Replicas — distribute read queries so each instance handles fewer requests' }, { id: 'B', text: 'Upgrade to a memory-optimized instance type (R class) — larger shared_buffers caches more of the working dataset in RAM' }, { id: 'C', text: 'Enable Multi-AZ — cross-AZ synchronization reduces primary read load during replication' }, { id: 'D', text: 'Increase EBS IOPS — faster disk reads reduce the time spent waiting when cache misses occur' }], correct: ['B'], explanation: 'High cache miss ratio means the working dataset exceeds memory (shared_buffers). Upgrading to an R-class instance (more RAM) allows PostgreSQL to cache more data, dramatically reducing disk I/O.', distractors: { A: 'Read replicas distribute query load — but each replica has the same memory constraint and the same cache miss problem.', C: 'Multi-AZ provides HA — standby replication does not reduce primary read load.', D: 'More IOPS handles disk reads faster — but adding RAM eliminates the disk reads entirely, which is more effective.' } },
  { id: 'd3-db-027', domain: 3, topics: ['DynamoDB', 'conditional writes', 'optimistic locking'], type: 'single', stem: 'Two Lambda functions might update the same DynamoDB item simultaneously, causing lost updates. What prevents overwriting stale data?', options: [{ id: 'A', text: 'DynamoDB Transactions — wrap both Lambda writes in a TransactWriteItems for mutual exclusion' }, { id: 'B', text: 'Conditional writes with a version attribute — write fails if another process already incremented the version' }, { id: 'C', text: 'DynamoDB Streams — detect conflicting writes after the fact and trigger compensating transactions' }, { id: 'D', text: 'DynamoDB Global Tables conflict resolution — automatically detects and resolves concurrent write conflicts' }], correct: ['B'], explanation: 'Conditional writes implement optimistic locking: include condition_expression="version = :expected_version". If another Lambda incremented the version, the condition fails and the write is rejected. The Lambda retries with fresh data.', distractors: { A: 'Transactions are for atomic multi-item operations — conditional writes handle single-item optimistic locking more efficiently for this pattern.', C: 'Streams capture changes after they occur — they do not prevent concurrent writes from overwriting each other.', D: 'Global Tables conflict resolution uses last-writer-wins for multi-region conflicts — not an optimistic locking mechanism.' } },
  { id: 'd3-db-028', domain: 3, topics: ['Keyspaces', 'Cassandra', 'migration'], type: 'single', stem: 'A company runs Apache Cassandra and wants a managed AWS service with no application code changes (CQL must work unchanged). Which service is compatible?', options: [{ id: 'A', text: 'Amazon DynamoDB — NoSQL with compatible APIs that accept Cassandra CQL statements' }, { id: 'B', text: 'Amazon Keyspaces (for Apache Cassandra) — serverless, Cassandra-compatible, CQL queries work without changes' }, { id: 'C', text: 'Amazon RDS with Cassandra compatibility mode enabled in the parameter group' }, { id: 'D', text: 'Amazon Aurora with Cassandra plugin for CQL query translation layer' }], correct: ['B'], explanation: 'Amazon Keyspaces is a serverless Cassandra-compatible managed database. Existing Cassandra applications using CQL work without code changes. No cluster management, automatic scaling, three-AZ durable storage.', distractors: { A: 'DynamoDB uses its own proprietary API — not CQL compatible. Cassandra application code would require a complete rewrite.', C: 'RDS runs relational databases (MySQL, PostgreSQL, etc.) — there is no Cassandra compatibility mode.', D: 'Aurora runs MySQL/PostgreSQL — no Cassandra plugin or CQL translation layer exists.' } },
  { id: 'd3-db-029', domain: 3, topics: ['Timestream', 'time-series', 'IoT'], type: 'single', stem: 'An IoT platform ingests 10 million data points per minute from sensors. Queries analyze time-series trends. Which AWS database is purpose-built for this?', options: [{ id: 'A', text: 'DynamoDB with timestamp sort key — sorts sensor readings within each device partition for range queries' }, { id: 'B', text: 'Amazon Timestream — serverless time-series database with automatic tiering, built-in time-series functions' }, { id: 'C', text: 'RDS with a time-series schema and partitioned tables for each time range' }, { id: 'D', text: 'S3 + Athena — store sensor data in Parquet on S3 and query with Athena for ad-hoc analysis' }], correct: ['B'], explanation: 'Amazon Timestream is purpose-built for time-series data: automatic data tiering (recent in memory, historical on magnetic), built-in time-series functions (interpolation, smoothing), scales to trillions of events per day.', distractors: { A: 'DynamoDB can store time-series data but lacks time-series-specific query functions and automatic storage tiering by age.', C: 'RDS can store time-series but does not scale to 10 million data points per minute without extreme schema and partitioning optimization.', D: 'S3 + Athena provides ad-hoc analytics — it cannot ingest and query 10M data points per minute in real time.' } },
  { id: 'd3-db-030', domain: 3, topics: ['Aurora', 'Backtrack', 'fast recovery'], type: 'single', stem: 'An Aurora MySQL cluster has Backtrack enabled (24-hour window). A bad query deleted rows at 3 PM. The team discovers this at 4 PM. What is the fastest recovery method?', options: [{ id: 'A', text: 'PITR restore — create a new Aurora cluster from the point-in-time backup taken before the deletion' }, { id: 'B', text: 'Aurora Backtrack — rewind the existing cluster in-place to 2:59 PM in minutes without creating a new cluster' }, { id: 'C', text: 'Restore from the most recent daily automated snapshot taken last night' }, { id: 'D', text: 'Read from the Aurora read replica before it replicates the deletion from the primary storage volume' }], correct: ['B'], explanation: 'Aurora Backtrack rewinds the cluster in-place to the specified time (within the backtrack window). Takes minutes — the same cluster endpoint, no DNS updates, no application changes needed. Faster than PITR.', distractors: { A: 'PITR creates a new cluster which takes longer and requires connection string updates in the application.', C: 'Daily snapshot would restore to last night\'s state, losing all legitimate data written since then.', D: 'Aurora replicas share the same distributed storage volume — the deletion is immediately visible on all replicas.' } },
  { id: 'd3-db-031', domain: 3, topics: ['DAX', 'cache staleness', 'consistency'], type: 'single', stem: 'An app uses DAX in front of DynamoDB. After a direct DynamoDB write (bypassing DAX), an immediate read returns stale data. Why?', options: [{ id: 'A', text: 'DynamoDB is eventually consistent — the base table has not yet committed the write' }, { id: 'B', text: 'DAX caches reads — a cached version may be served until the TTL expires; writes bypassing DAX do not update the cache' }, { id: 'C', text: 'The write was queued by DynamoDB and has not yet been applied to the storage layer' }, { id: 'D', text: 'DAX does not support strongly consistent reads — all reads are eventually consistent through the cache' }], correct: ['B'], explanation: 'DAX maintains an item cache. Writes that go directly to DynamoDB (bypassing DAX) do not update the DAX cache. The cache serves the old version until TTL expires. Write through DAX to keep the cache consistent.', distractors: { A: 'DynamoDB itself provides strong read-after-write consistency — the issue is DAX cache staleness, not DynamoDB consistency.', C: 'DynamoDB writes are committed synchronously — the write is persisted before returning success.', D: 'DAX does support strongly consistent reads via GetItem with ConsistentRead=true — these bypass the item cache and go to DynamoDB.' } },
  { id: 'd3-db-032', domain: 3, topics: ['Neptune', 'graph database', 'traversal'], type: 'single', stem: 'A social network application runs "friends of friends of friends" queries. Multi-hop JOIN queries in RDS are becoming exponentially slow. What database type solves this?', options: [{ id: 'A', text: 'RDS MySQL with recursive CTEs — modern SQL handles multi-hop traversal queries efficiently' }, { id: 'B', text: 'Amazon Neptune — purpose-built graph database using Gremlin/openCypher for efficient multi-hop traversal' }, { id: 'C', text: 'DynamoDB with adjacency list design pattern for modeling graph relationships' }, { id: 'D', text: 'Amazon OpenSearch — full-text search indexes relationship data for fast multi-hop queries' }], correct: ['B'], explanation: 'Graph databases (Neptune) are optimized for connected data. Multi-hop traversals are O(relationship count), not O(table size) — vs. SQL JOINs that become exponentially expensive as hop count increases.', distractors: { A: 'Recursive CTEs in SQL work but performance degrades exponentially at scale — graph databases are designed for this access pattern.', C: 'DynamoDB adjacency lists work for simple graphs but still require multiple round trips per hop at scale.', D: 'OpenSearch is a search and analytics engine — not a graph database with traversal query language.' } },
  { id: 'd3-db-033', domain: 3, topics: ['Redshift', 'AQUA', 'query acceleration'], type: 'single', stem: 'A Redshift cluster runs complex analytics on petabytes of data. Queries are slow because data must move from Managed Storage to compute nodes. What feature reduces this bottleneck?', options: [{ id: 'A', text: 'Redshift Serverless — automatically provisions additional compute capacity for large analytical queries' }, { id: 'B', text: 'AQUA (Advanced Query Accelerator) — hardware-accelerated cache near storage that executes filtering locally' }, { id: 'C', text: 'Redshift Spectrum — queries data in S3 directly without loading into Redshift cluster storage' }, { id: 'D', text: 'Materialized Views — pre-computes common query results and serves them from cache without re-scanning data' }], correct: ['B'], explanation: 'AQUA is a distributed hardware-accelerated cache near Redshift Managed Storage. Executes filtering and aggregation locally before sending results to compute nodes — dramatically reducing data transfer for large analytical queries.', distractors: { A: 'Redshift Serverless manages capacity automatically — not a query acceleration layer that reduces storage-to-compute data movement.', C: 'Redshift Spectrum queries S3 data — does not address the storage-to-compute bandwidth for data already in Redshift.', D: 'Materialized Views pre-compute results for repeated queries — do not address data transfer bottlenecks during initial query execution.' } },
  { id: 'd3-db-034', domain: 3, topics: ['DynamoDB', 'single-table design', 'access patterns'], type: 'single', stem: 'A DynamoDB e-commerce app needs to query "all orders for a customer" and "all items in an order" efficiently. What design approach enables both?', options: [{ id: 'A', text: 'Separate tables for customers, orders, and items with DynamoDB BatchGetItem to join them in the application' }, { id: 'B', text: 'Single-table design — PK=CustomerId, SK=ORDER#orderId for orders and SK=ITEM#orderId#itemId for items' }, { id: 'C', text: 'Scan the table for all queries and use FilterExpression to extract customers, orders, and items' }, { id: 'D', text: 'One GSI per access pattern — a GSI for customer lookups and a separate GSI for item lookups' }], correct: ['B'], explanation: 'Single-table design: PK=CustomerId, SK=ORDER#orderId for order records; SK=ITEM#orderId#itemId for item records. Query by PK gets all customer orders; Query by PK with SK prefix filter gets items within an order.', distractors: { A: 'DynamoDB does not support JOINs — multiple tables require N+1 query patterns and application-level joins.', C: 'Scans are O(n) — single-table design with the right key structure eliminates the need for scans.', D: 'Multiple GSIs add storage cost and write amplification — single-table design with structured SK often eliminates the need for extra GSIs.' } },
  { id: 'd3-db-035', domain: 3, topics: ['OpenSearch', 'full-text search', 'DynamoDB'], type: 'single', stem: 'A product catalog in DynamoDB needs full-text search with fuzzy matching and relevance scoring. DynamoDB does not support this natively. What architecture adds search?', options: [{ id: 'A', text: 'Add a GSI on the product description attribute — enables DynamoDB Query with contains() condition' }, { id: 'B', text: 'DynamoDB Streams → Lambda → OpenSearch — stream changes to OpenSearch for full-text indexing' }, { id: 'C', text: 'Use Athena with DynamoDB connector and LIKE queries for full-text search capabilities' }, { id: 'D', text: 'Migrate the catalog from DynamoDB to RDS and use MySQL FULLTEXT indexes for search' }], correct: ['B'], explanation: 'DynamoDB Streams → Lambda → OpenSearch is the canonical pattern. Lambda processes stream records and indexes items in OpenSearch. Search queries go to OpenSearch; transactional reads/writes go to DynamoDB.', distractors: { A: 'DynamoDB GSIs support exact key lookups and range queries — not full-text search, fuzzy matching, or relevance scoring.', C: 'Athena DynamoDB connector exists but LIKE queries do not provide relevance scoring or fuzzy matching.', D: 'Migrating to RDS requires application code changes and MySQL FULLTEXT has limitations vs. OpenSearch at scale.' } },
  { id: 'd3-db-036', domain: 3, topics: ['ElastiCache', 'eviction policy', 'cache full'], type: 'single', stem: 'An ElastiCache Redis cache is near memory capacity. New items need to be added. What eviction policy removes the least recently used items?', options: [{ id: 'A', text: 'noeviction — returns errors for writes when memory is full, preserving all existing data' }, { id: 'B', text: 'allkeys-lru — evicts the least recently used key from the entire keyspace when memory limit is reached' }, { id: 'C', text: 'volatile-lru — evicts LRU keys but only from keys that have a TTL set, preserving keys without TTL' }, { id: 'D', text: 'allkeys-random — evicts randomly selected keys, distributing eviction across all stored data equally' }], correct: ['B'], explanation: 'allkeys-lru evicts the least recently used keys across all keys when memory limit is reached. Best for caches where all data can be re-fetched from the source. Most common cache eviction policy.', distractors: { A: 'noeviction is for Redis used as a primary store — errors on write are not acceptable for a cache use case.', C: 'volatile-lru only evicts keys with TTL set — keys without TTL never get evicted, limiting eviction effectiveness.', D: 'allkeys-random evicts randomly — recently hot keys may be evicted, degrading cache effectiveness.' } },
  { id: 'd3-db-037', domain: 3, topics: ['Aurora', 'ML integration', 'SQL'], type: 'single', stem: 'A data analyst needs to run sentiment analysis on reviews stored in Aurora PostgreSQL without exporting data or writing Python. What feature enables ML via SQL?', options: [{ id: 'A', text: 'Aurora Lambda integration — call a custom Lambda function from SQL to invoke ML models' }, { id: 'B', text: 'Aurora ML integration — call Comprehend or SageMaker models directly from SQL SELECT statements' }, { id: 'C', text: 'Export reviews to S3 and run Comprehend batch jobs, then reimport results into Aurora' }, { id: 'D', text: 'Redshift ML — train models and run inference from SQL directly in the Redshift data warehouse' }], correct: ['B'], explanation: 'Aurora ML integration provides SQL functions that call SageMaker and Amazon Comprehend directly. Use aws_comprehend.detect_sentiment() in a SQL SELECT — no data export or Python code needed.', distractors: { A: 'Aurora Lambda integration calls custom Lambda functions from SQL — requires writing and deploying Lambda code for each ML operation.', C: 'Export to S3 + Comprehend batch requires external orchestration and data movement — Aurora ML keeps the workflow in SQL.', D: 'Redshift ML is for Redshift data warehouse — not for Aurora PostgreSQL databases.' } },
  { id: 'd3-db-038', domain: 3, topics: ['DynamoDB', 'Export to S3', 'Athena'], type: 'single', stem: 'A team needs to analyze historical DynamoDB table data in Athena without impacting production table performance. What built-in feature enables this?', options: [{ id: 'A', text: 'DynamoDB Scan with parallel segments, writing output to S3 — distributes scan load across segments' }, { id: 'B', text: 'DynamoDB Export to S3 — exports table to S3 in JSON/Parquet format without consuming read capacity' }, { id: 'C', text: 'DynamoDB Streams to Kinesis Firehose to S3 — continuous pipeline delivering changes to S3 for Athena' }, { id: 'D', text: 'AWS Glue DynamoDB connector with a crawl job writing Parquet to S3 for Athena analysis' }], correct: ['B'], explanation: 'DynamoDB Export to S3 (point-in-time export) exports the full table to S3 in DynamoDB JSON, ION, or Parquet format without consuming read capacity or impacting table performance.', distractors: { A: 'Parallel Scan exports data but consumes RCUs and can impact table performance — Export to S3 is designed to avoid this.', C: 'Streams + Kinesis provides a continuous change pipeline — appropriate for incremental updates, not clean historical snapshots.', D: 'AWS Glue DynamoDB connector reads the table directly and consumes RCUs — DynamoDB Export is the zero-impact option.' } },
  { id: 'd3-db-039', domain: 3, topics: ['RDS', 'Storage Auto Scaling', 'trigger'], type: 'single', stem: 'When does RDS Storage Auto Scaling automatically increase storage?', options: [{ id: 'A', text: 'RDS increases storage on a fixed weekly schedule to stay ahead of projected growth' }, { id: 'B', text: 'When free storage is below 10% for 5+ minutes AND at least 6 hours have passed since the last expansion' }, { id: 'C', text: 'When any write operation fails due to insufficient storage space on the volume' }, { id: 'D', text: 'When a CloudWatch alarm configured during RDS creation fires based on FreeStorageSpace metric' }], correct: ['B'], explanation: 'RDS Storage Auto Scaling triggers when: (1) free storage < 10% of allocated, (2) low storage has lasted ≥5 minutes, AND (3) ≥6 hours since the last auto scaling. Increases by max of 5 GB, 10% of allocated, or 7× daily I/O.', distractors: { A: 'RDS storage scaling is reactive to actual usage, not a fixed weekly schedule.', C: 'RDS proactively scales before running out — it does not wait for write failures.', D: 'Storage Auto Scaling is built-in and self-managed — not triggered by user-configured CloudWatch alarms.' } },
  { id: 'd3-db-040', domain: 3, topics: ['DynamoDB Global Tables', 'replication lag'], type: 'single', stem: 'A DynamoDB Global Tables write occurs in us-east-1. How long does it typically take for the change to appear in eu-west-1?', options: [{ id: 'A', text: 'Immediately — Global Tables uses synchronous cross-region replication for strong consistency' }, { id: 'B', text: 'Typically under 1 second — asynchronous replication via DynamoDB Streams across regions' }, { id: 'C', text: '5-10 minutes — same as RDS cross-region read replica replication lag' }, { id: 'D', text: 'Up to 24 hours — bounded by the DynamoDB Streams record retention period' }], correct: ['B'], explanation: 'DynamoDB Global Tables replicates within typically under 1 second (often milliseconds) using an asynchronous Streams-based process. RPO is approximately 1 second under normal operation.', distractors: { A: 'Global Tables uses asynchronous replication — synchronous would add cross-region round-trip latency to every write.', C: '5-10 minutes is the typical lag for RDS cross-region read replicas — DynamoDB Global Tables is sub-second.', D: 'Streams retention period (24 hours) is how long records are available for consumers — not the replication latency.' } },
  { id: 'd3-db-041', domain: 3, topics: ['Redshift Spectrum', 'data lake query'], type: 'single', stem: 'A company has 5 PB in S3 and 100 GB in Redshift. They want SQL queries joining both without loading S3 data into Redshift. What enables this?', options: [{ id: 'A', text: 'Redshift COPY command — loads S3 data into Redshift staging tables for JOIN with permanent tables' }, { id: 'B', text: 'Redshift Spectrum — defines external tables over S3 data; JOIN with Redshift tables in one SQL statement' }, { id: 'C', text: 'Athena federated query with Redshift connector — Athena executes queries spanning both data sources' }, { id: 'D', text: 'AWS Glue crawler to catalog S3 and Redshift data, then query via Glue Studio' }], correct: ['B'], explanation: 'Redshift Spectrum queries S3 data directly via external tables (catalog in Glue/Redshift external schema). JOIN Redshift tables with S3 data in one SQL statement — Redshift\'s query planner handles both.', distractors: { A: 'COPY loads data into Redshift storage — storing 5 PB in Redshift would be cost-prohibitive.', C: 'Athena federated query can span data sources but does not provide Redshift-native SQL query planning across both.', D: 'Glue Studio is for ETL pipelines — not for interactive SQL JOIN queries across Redshift and S3.' } },
  { id: 'd3-db-042', domain: 3, topics: ['DynamoDB', 'RCU calculation', 'eventually consistent'], type: 'single', stem: 'A DynamoDB table processes 5,000 eventually consistent reads per second for 8 KB items. How many RCUs are required?', options: [{ id: 'A', text: '5,000 RCUs — one RCU per read regardless of item size for eventually consistent reads' }, { id: 'B', text: '10,000 RCUs — eventually consistent 8 KB reads cost 2 RCUs each (1 RCU per 4 KB × 2)' }, { id: 'C', text: '20,000 RCUs — each 8 KB item needs 4 RCUs for strongly consistent reads at this volume' }, { id: 'D', text: '5,000 RCUs — (8 KB / 4 KB) × 0.5 EC multiplier × 5,000 reads = 5,000 RCUs' }], correct: ['D'], explanation: 'Eventually consistent read: 0.5 RCU per 4 KB. For 8 KB item: (8/4) × 0.5 = 1 RCU per read. For 5,000 reads/sec: 5,000 RCUs. The formula: ceil(item_KB/4) × 0.5 (EC) × reads/sec.', distractors: { A: '1 RCU per read regardless of size is wrong — items over 4 KB consume additional RCUs even for eventually consistent reads.', B: '10,000 would be correct for strongly consistent 8 KB reads — eventually consistent halves the cost to 5,000.', C: '20,000 is the cost for strongly consistent reads of 16 KB items — not eventually consistent 8 KB items.' } },
  { id: 'd3-db-043', domain: 3, topics: ['Redshift', 'distribution styles', 'ALL distribution'], type: 'single', stem: 'A Redshift 1,000-row dimension table is frequently joined with fact tables. Query performance is slow due to data movement during joins. What distribution style minimizes data movement?', options: [{ id: 'A', text: 'KEY distribution — distribute fact and dimension tables on the same join column to co-locate matching rows' }, { id: 'B', text: 'ALL distribution — copy the entire dimension table to every compute node, eliminating data movement in joins' }, { id: 'C', text: 'EVEN distribution — evenly spread dimension rows across nodes for balanced parallel scanning' }, { id: 'D', text: 'AUTO distribution — Redshift chooses the best style based on table size and query patterns automatically' }], correct: ['B'], explanation: 'For small dimension tables, ALL distribution copies the table to every node. JOINs find dimension data locally on each node — no broadcast needed. Suitable for tables under ~3 million rows.', distractors: { A: 'KEY distribution co-locates rows with matching join keys — requires the fact table to also be distributed on the same key, which may not be optimal.', C: 'EVEN distribution spreads rows randomly — JOINs still require moving data across nodes to find matching rows.', D: 'AUTO may choose ALL for small tables, but explicit ALL is the targeted optimization for this known small dimension table.' } },
  { id: 'd3-db-044', domain: 3, topics: ['Aurora', 'RDS Proxy', 'connection management'], type: 'single', stem: 'An Aurora PostgreSQL cluster receives 10,000 concurrent connections, causing high memory and connection overhead. What service reduces the actual database connections?', options: [{ id: 'A', text: 'Increase Aurora max_connections parameter — allow 10,000+ connections to the cluster directly' }, { id: 'B', text: 'Amazon RDS Proxy — pools connections; 10,000 app connections multiplex through a smaller DB connection pool' }, { id: 'C', text: 'Add more Aurora read replicas — distribute the 10,000 connections across more DB instances' }, { id: 'D', text: 'Enable Aurora Serverless v2 — dynamic ACU scaling accommodates the 10,000 connection overhead automatically' }], correct: ['B'], explanation: 'RDS Proxy maintains a pool of long-lived connections to Aurora. 10,000 application connections connect to Proxy (lightweight). Proxy maintains a much smaller pool of actual DB connections — reduces memory and overhead.', distractors: { A: 'max_connections allows more connections but each PostgreSQL connection consumes ~5-10 MB RAM — 10,000 connections = ~50-100 GB just for connection overhead.', C: 'Read replicas add query capacity — each replica still faces the same per-connection memory overhead on its own.', D: 'Serverless v2 scales compute ACUs — does not reduce the number of connections or per-connection memory overhead.' } },
  { id: 'd3-db-045', domain: 3, topics: ['DynamoDB', 'Standard-IA', 'low access cost'], type: 'single', stem: 'A DynamoDB table stores compliance audit logs rarely queried but retained for 7 years. How can storage costs be reduced without losing DynamoDB query access?', options: [{ id: 'A', text: 'Move the data to S3 and use Athena — eliminates DynamoDB storage costs for the compliance logs' }, { id: 'B', text: 'Switch to DynamoDB Standard-IA table class — reduces storage cost by ~60% for infrequently accessed tables' }, { id: 'C', text: 'Enable DynamoDB TTL after 7 years — ensures data is retained exactly as long as required then deleted' }, { id: 'D', text: 'Use DynamoDB Streams to archive items to S3 Glacier, keeping only index records in DynamoDB' }], correct: ['B'], explanation: 'DynamoDB Standard-IA table class reduces storage costs by ~60% vs. Standard. Higher read/write costs (acceptable for rarely queried tables). Ideal for long-term retention tables like compliance logs and audit trails.', distractors: { A: 'Moving to S3 means losing DynamoDB query access — if audit queries using DynamoDB APIs are needed, Standard-IA preserves this.', C: 'TTL deletes items after expiry — useful for the 7-year enforcement, but does not reduce storage cost during the retention period.', D: 'Archiving to S3 Glacier via Streams requires complex pipeline code — Standard-IA is a simple table setting change.' } },
]
